IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[Catalog].[WarehouseGroup]') AND type in (N'U'))
BEGIN
        CREATE TABLE [Catalog].[WarehouseGroup](
                [Id] [int] IDENTITY(1,1) NOT NULL,
                [ExternalId] [nvarchar](50) NULL,
                [Name] [nvarchar](255) NOT NULL,
                [Enabled] [bit] NOT NULL,
                [Description] [nvarchar](max) NULL,
                [SortOrder] [int] NOT NULL,
                [Phone] [nvarchar](50) NULL,
                [CountryId] [int] NULL,
                [RegionId] [int] NULL,
                [CityId] [int] NULL,
                [Vk] [nvarchar](255) NULL,
                [Facebook] [nvarchar](255) NULL,
                [Instagram] [nvarchar](255) NULL,
                [Twitter] [nvarchar](255) NULL,
                [OkRu] [nvarchar](255) NULL,
                [Youtube] [nvarchar](255) NULL,
                [Zen] [nvarchar](255) NULL,
                [Rutube] [nvarchar](255) NULL,
        CONSTRAINT [PK_WarehouseGroup] PRIMARY KEY CLUSTERED 
        (
                [Id] ASC
        )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
        ) ON [PRIMARY] 
END

