CREATE FUNCTION [dbo].[NvarcharToBigint] (@input NVARCHAR(MAX))
    RETURNS BIGINT
AS
BEGIN
    IF @input IS NULL
        RETURN NULL;

    DECLARE
        @result NVARCHAR(MAX) = '', 
        @index INT = 1;
    
    WHILE @index <= LEN(@input) AND LEN(@result) <= 17
        BEGIN
            DECLARE @char NCHAR(1) = SUBSTRING(@input, @index, 1);
    
            IF @char LIKE '[0-9]'
                BEGIN
                    SET @result = @result + @char;
                END;
    
            SET @index = @index + 1;
        END;
        
    IF LEN(@result) <= 1
        RETURN NULL;
    
    RETURN CAST(@result AS BIGINT);
END;

