IF EXISTS(
	SELECT * FROM [Order].[ShippingParam]
	INNER JOIN [Order].[ShippingMethod] ON [ShippingMethod].ShippingMethodID = [ShippingParam].ShippingMethodID
	WHERE [ShippingMethod].[ShippingType] = 'Yandex' AND [ShippingMethod].Enabled = 1 AND [ShippingParam].[ParamName] = 'PaymentCodCardId' AND [ShippingParam].[ParamValue] <> '')
BEGIN
	WITH ShippingParams (RowNumber, shipMethodId, paramName, paramValue) AS
	(
		SELECT RowNumber = ROW_NUMBER() OVER (PARTITION BY [PaymentParam].Value ORDER BY [PaymentParam].Value), CAST([PaymentParam].Value AS INT) as shipMethodId, 'PaymentCodCashId' as paramName, CAST([PaymentMethod].PaymentMethodID AS nvarchar) as paramValue 
		FROM [Order].[PaymentMethod]
		INNER JOIN [Order].[PaymentParam] ON [PaymentParam].PaymentMethodID = PaymentMethod.PaymentMethodID AND [PaymentParam].Name = 'ShippingMethod'
		WHERE [PaymentMethod].PaymentType = 'CashOnDelivery' AND [PaymentParam].Value <> '' 
		AND EXISTS (SELECT * FROM [Order].[ShippingMethod] 
		WHERE [ShippingMethod].ShippingMethodID = CAST([PaymentParam].Value AS INT) 
		AND [ShippingMethod].[ShippingType] = 'Yandex')
		AND NOT EXISTS (SELECT * FROM [Order].[ShippingParam] 
		WHERE ShippingParam.ShippingMethodID = CAST([PaymentParam].Value AS INT) 
		AND (ShippingParam.ParamName = 'PaymentCodCardId'
		AND ShippingParam.ParamValue = CAST([PaymentMethod].PaymentMethodID AS nvarchar)
		OR ShippingParam.ParamName = 'PaymentCodCashId'
		AND ShippingParam.ParamValue <> ''))
	)
	INSERT INTO [Order].[ShippingParam] (ShippingMethodID, ParamName, ParamValue)
	SELECT shipMethodId, paramName, paramValue FROM ShippingParams where RowNumber = 1
END

