if not exists (Select 1 From [Settings].[Settings] Where Name = 'SettingsVk.UserTokenData') and 
       exists (Select 1 From [Settings].[Settings] Where Name = 'SettingsVk.TokenUser' and [Value] IS NOT NULL and LTRIM(RTRIM(Value)) <> '')
begin
	-- save TokenUser to UserTokenData json
	Insert Into [Settings].[Settings] (Name, Value) 
	Select 'SettingsVk.UserTokenData', 
		   '{"refresh_token":null,"access_token":"' + [Value] + '","id_token":null,"token_type":null,"expires_in":0,"user_id":0,"state":null,"scope":null,"device_id":null,"client_id":null}' 
	From [Settings].[Settings] 
	Where Name = 'SettingsVk.TokenUser'
	
	-- rename TokenUser setting
	Update [Settings].[Settings] 
	Set [Name] = 'SettingsVk.TokenUser_previous'
	Where Name = 'SettingsVk.TokenUser'

	-- set use old integration (without refresh token)
	Insert Into [Settings].[Settings] (Name, Value) Values ('SettingsVk.IsOldIntegration', 'True') 
end

GO--
DECLARE @QuickViewExists BIT, @OpenQuickViewExists BIT;
DECLARE @Template VARCHAR(50);

CREATE TABLE #Templates (TemplateName VARCHAR(50));
INSERT INTO #Templates VALUES ('Sushi'), ('Gurman'), ('Boston'), ('Milan'), ('Paris'), ('Tbilisi'), ('Monaco');

DECLARE TemplateCursor CURSOR FOR 
SELECT TemplateName FROM #Templates;

OPEN TemplateCursor;
FETCH NEXT FROM TemplateCursor INTO @Template;

WHILE @@FETCH_STATUS = 0
BEGIN
    SET @QuickViewExists = 0;
    IF EXISTS (
        SELECT 1 FROM [Settings].[TemplateSettings] 
        WHERE [Template] = @Template AND [Name] = 'QuickViewAsProductPage'
    )
    BEGIN
        SET @QuickViewExists = 1;
    END
    
    SET @OpenQuickViewExists = 0;
    IF EXISTS (
        SELECT 1 FROM [Settings].[TemplateSettings] 
        WHERE [Template] = @Template AND [Name] = 'OpenQuickViewAlways'
    )
    BEGIN
        SET @OpenQuickViewExists = 1;
    END
	
    IF @QuickViewExists = 0 AND @OpenQuickViewExists = 1
    BEGIN
        INSERT INTO [Settings].[TemplateSettings] ([Template], [Name], [Value]) 
        SELECT @Template, 'QuickViewAsProductPage', [Value] 
        FROM [Settings].[TemplateSettings] 
        WHERE [Template] = @Template AND [Name] = 'OpenQuickViewAlways';
    END
    
    
    FETCH NEXT FROM TemplateCursor INTO @Template;
END

CLOSE TemplateCursor;
DEALLOCATE TemplateCursor;

DROP TABLE #Templates;

