GO--
IF EXISTS(SELECT * FROM [Settings].[Settings] WHERE [Name] = 'ShowSpinboxInCatalog')
BEGIN
	IF (SELECT TOP(1) [Value] FROM [Settings].[Settings] WHERE [Name] = 'ShowSpinboxInCatalog') = 'true'
	BEGIN
        IF EXISTS (SELECT * FROM [Settings].[Settings] WHERE [Name] = 'CartAddType')
            UPDATE [Settings].[Settings] SET [Value] = '2' WHERE [Name] = 'CartAddType'
	    ELSE
            INSERT INTO [Settings].[Settings] ([Value], [Name]) VALUES ('2', 'CartAddType')
    END

	DELETE FROM [Settings].[Settings] WHERE [Name] = 'ShowSpinboxInCatalog'
END

IF EXISTS(SELECT * FROM [Settings].[TemplateSettings] WHERE [Name] = 'ShowSpinboxInCatalog')
BEGIN
	WITH CTE_ForUpdate AS (
		SELECT
			Template,
			Value
		FROM 
			[Settings].[TemplateSettings] settingsTemplate
		WHERE [Name] = 'ShowSpinboxInCatalog' AND [Value] = 'true' AND
        EXISTS (SELECT * FROM [Settings].[TemplateSettings] settingsTemplate2 WHERE settingsTemplate.Template = settingsTemplate2.Template AND settingsTemplate2.Name = 'CartAddType')
	)

	UPDATE settingsTemplate
	SET settingsTemplate.Value = case settingsTemplate.Template when 'Sushi' then '1' else '2' end
	FROM [Settings].[TemplateSettings] settingsTemplate
	INNER JOIN CTE_ForUpdate cte ON cte.Template = settingsTemplate.Template
	WHERE settingsTemplate.Name = 'CartAddType'; 
	
	WITH CTE_ForInsert AS (
		SELECT
			Template,
			Value
		FROM 
			[Settings].[TemplateSettings] settingsTemplate
		WHERE [Name] = 'ShowSpinboxInCatalog' AND [Value] = 'true' AND
        NOT EXISTS (SELECT * FROM [Settings].[TemplateSettings] settingsTemplate2 WHERE settingsTemplate.Template = settingsTemplate2.Template AND settingsTemplate2.Name = 'CartAddType')
	)

    INSERT INTO [Settings].[TemplateSettings] (Template, Name, Value)
    SELECT Template, 'CartAddType', case Template when 'Sushi' then '1' else '2' end FROM CTE_ForInsert

	DELETE FROM [Settings].[TemplateSettings] WHERE [Name] = 'ShowSpinboxInCatalog'
END

